(()=>{const controls=[...document.querySelectorAll('[data-marine-tool]')];if(!controls.length)return;const descriptions={"marine-bom":{problem:"Going through 50–100+ page drawing sets and manually calculating how much of each material is needed is extremely tedious.",solution:"I used computer vision and OCR to extract drawing BOMs into an assembly-aware Excel workbook for material-quantity review."},"marine-cad":{problem:"Manually arranging ship parts on stock plates is tedious layout work.",solution:"I built a part-nesting engine using backtracking and dynamic programming, connected to AutoCAD through MCP and the C#/.NET API."}};function select(button){const text=descriptions[button.dataset.marineTool];document.getElementById("marine-problem").textContent=text.problem;document.getElementById("marine-solution").textContent=text.solution;for(const control of controls){const open=control===button;control.setAttribute('aria-expanded',String(open));control.querySelector('b').textContent=open?'−':'+';document.getElementById(control.dataset.marineTool).hidden=!open}}controls.forEach((button,i)=>{button.addEventListener('click',()=>select(button));button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const index=event.key==='Home'?0:event.key==='End'?controls.length-1:(i+(event.key==='ArrowRight'?1:-1)+controls.length)%controls.length;controls[index].focus();select(controls[index])})})})();
